"""Tests for invtrack.inventory business logic."""

import pytest
from pathlib import Path

from invtrack.store import Store
from invtrack.inventory import add, adjust, low_stock


@pytest.fixture
def store(tmp_path: Path) -> Store:
    """Provide a fresh in-memory-backed Store for each test."""
    return Store(tmp_path / "test.json")


# ── add ────────────────────────────────────────────────

def test_add_item_basic(store: Store) -> None:
    add(store, "Widget", 10, 5)
    assert store.get("Widget") == {"quantity": 10, "reorder_level": 5}


def test_add_item_default_reorder_level(store: Store) -> None:
    add(store, "Widget", 10)
    assert store.get("Widget") == {"quantity": 10, "reorder_level": 0}


def test_add_item_duplicate_name_raises(store: Store) -> None:
    add(store, "Widget", 10)
    with pytest.raises(ValueError, match="Item already exists"):
        add(store, "Widget", 5)


def test_add_item_zero_quantity(store: Store) -> None:
    add(store, "Empty", 0)
    assert store.get("Empty") == {"quantity": 0, "reorder_level": 0}


def test_add_item_reorder_level_preserved(store: Store) -> None:
    add(store, "Widget", 10, reorder_level=7)
    assert store.get("Widget")["reorder_level"] == 7


# ── adjust ─────────────────────────────────────────────

def test_adjust_item_positive_delta(store: Store) -> None:
    add(store, "Widget", 10)
    adjust(store, "Widget", 5)
    assert store.get("Widget")["quantity"] == 15


def test_adjust_item_negative_delta(store: Store) -> None:
    add(store, "Widget", 10)
    adjust(store, "Widget", -3)
    assert store.get("Widget")["quantity"] == 7


def test_adjust_item_zero_delta(store: Store) -> None:
    add(store, "Widget", 10)
    adjust(store, "Widget", 0)
    assert store.get("Widget")["quantity"] == 10


def test_adjust_item_unknown_name_raises(store: Store) -> None:
    with pytest.raises(ValueError, match="Item not found"):
        adjust(store, "Missing", 1)


def test_adjust_item_to_exactly_reorder_level(store: Store) -> None:
    add(store, "Widget", 10, reorder_level=5)
    adjust(store, "Widget", -5)
    assert store.get("Widget")["quantity"] == 5


def test_adjust_item_below_reorder_level(store: Store) -> None:
    add(store, "Widget", 10, reorder_level=5)
    adjust(store, "Widget", -6)
    assert store.get("Widget")["quantity"] == 4


def test_adjust_item_negative_result_raises(store: Store) -> None:
    add(store, "Widget", 2)
    with pytest.raises(ValueError, match="Quantity cannot go below 0"):
        adjust(store, "Widget", -5)


def test_adjust_item_to_zero_is_valid(store: Store) -> None:
    add(store, "Widget", 3)
    adjust(store, "Widget", -3)
    assert store.get("Widget")["quantity"] == 0


def test_adjust_item_reorder_level_unchanged(store: Store) -> None:
    add(store, "Widget", 10, reorder_level=5)
    adjust(store, "Widget", -3)
    assert store.get("Widget")["reorder_level"] == 5


# ── low_stock ──────────────────────────────────────────

def test_get_low_stock_empty_store(store: Store) -> None:
    assert low_stock(store) == []


def test_get_low_stock_all_items_below_reorder(store: Store) -> None:
    add(store, "A", 2, 5)
    add(store, "B", 0, 3)
    result = low_stock(store)
    assert len(result) == 2
    names = {item["name"] for item in result}
    assert names == {"A", "B"}


def test_get_low_stock_mixed_levels(store: Store) -> None:
    add(store, "A", 10, 5)
    add(store, "B", 2, 5)
    result = low_stock(store)
    assert len(result) == 1
    assert result[0]["name"] == "B"


def test_get_low_stock_exactly_at_reorder_level(store: Store) -> None:
    add(store, "Widget", 5, 5)
    result = low_stock(store)
    assert len(result) == 1
    assert result[0]["name"] == "Widget"


def test_get_low_stock_zero_reorder_level(store: Store) -> None:
    add(store, "A", 0, 0)
    add(store, "B", 5, 0)
    result = low_stock(store)
    assert len(result) == 1
    assert result[0]["name"] == "A"


def test_get_low_stock_returns_correct_shape(store: Store) -> None:
    add(store, "Widget", 2, 5)
    result = low_stock(store)
    assert len(result) == 1
    item = result[0]
    assert "name" in item and "quantity" in item and "reorder_level" in item
    assert item == {"name": "Widget", "quantity": 2, "reorder_level": 5}

"""Tests for invtrack/formatting.py — table and JSON output."""

import json
from unittest.mock import MagicMock

from invtrack.formatting import format_table


# ── text table: empty inventory ───────────────────────────────────────

def test_table_empty_inventory():
    result = format_table({}, fmt="text")
    lines = [l for l in result.splitlines() if l.strip()]
    assert len(lines) == 1  # header only
    assert "NAME" in lines[0] and "QTY" in lines[0]


# ── text table: single item, not low ──────────────────────────────────

def test_table_single_item_not_low():
    items = {"widget": {"quantity": 10, "reorder_level": 5}}
    result = format_table(items, fmt="text")
    assert "widget" in result
    assert "10" in result
    assert "LOW" not in result


# ── text table: single item, is low (qty == reorder) ─────────────────

def test_table_single_item_is_low():
    items = {"bolt": {"quantity": 3, "reorder_level": 3}}
    result = format_table(items, fmt="text")
    assert "bolt" in result
    assert "LOW" in result


# ── text table: single item, is low (qty < reorder) ──────────────────

def test_table_single_item_below_reorder():
    items = {"nut": {"quantity": 1, "reorder_level": 5}}
    result = format_table(items, fmt="text")
    assert "LOW" in result


# ── text table: multiple items, mixed low / not-low ───────────────────

def test_table_multiple_items_mixed():
    items = {
        "screw": {"quantity": 100, "reorder_level": 20},
        "washer": {"quantity": 5, "reorder_level": 10},
        "rivet": {"quantity": 0, "reorder_level": 0},
    }
    result = format_table(items, fmt="text")
    assert "screw" in result and "washer" in result and "rivet" in result
    # washer is low, screw is not; rivet (0 == 0) is low
    assert result.count("LOW") == 2


# ── text table: all items low ────────────────────────────────────────

def test_table_all_items_low():
    items = {
        "a": {"quantity": 0, "reorder_level": 1},
        "b": {"quantity": 2, "reorder_level": 5},
    }
    result = format_table(items, fmt="text")
    assert result.count("LOW") == 2


# ── text table: no items low ─────────────────────────────────────────

def test_table_no_items_low():
    items = {
        "a": {"quantity": 50, "reorder_level": 10},
        "b": {"quantity": 1, "reorder_level": 0},
    }
    result = format_table(items, fmt="text")
    assert "LOW" not in result


# ── text table: very long item name doesn't break alignment ───────────

def test_table_long_item_name():
    long_name = "A" * 60
    items = {long_name: {"quantity": 7, "reorder_level": 3}}
    result = format_table(items, fmt="text")
    assert long_name in result
    # should not raise and should contain the quantity
    assert "7" in result


# ── text table: zero reorder level, qty > 0 → not low ────────────────

def test_table_zero_reorder_not_low():
    items = {"gear": {"quantity": 1, "reorder_level": 0}}
    result = format_table(items, fmt="text")
    assert "LOW" not in result


# ── text table: zero reorder level, qty == 0 → low ───────────────────

def test_table_zero_reorder_qty_zero_is_low():
    items = {"gear": {"quantity": 0, "reorder_level": 0}}
    result = format_table(items, fmt="text")
    assert "LOW" in result


# ── JSON format: empty inventory ─────────────────────────────────────

def test_json_format_empty():
    result = format_table({}, fmt="json")
    parsed = json.loads(result)
    assert parsed == {}


# ── JSON format: single item ─────────────────────────────────────────

def test_json_format_single_item():
    items = {"bolt": {"quantity": 42, "reorder_level": 10}}
    result = format_table(items, fmt="json")
    parsed = json.loads(result)
    assert parsed == {"bolt": {"quantity": 42, "reorder_level": 10}}


# ── JSON format: multiple items, shape preserved ─────────────────────

def test_json_format_multiple_items():
    items = {
        "a": {"quantity": 1, "reorder_level": 0},
        "b": {"quantity": 2, "reorder_level": 5},
    }
    result = format_table(items, fmt="json")
    parsed = json.loads(result)
    assert len(parsed) == 2
    for name, val in parsed.items():
        assert "quantity" in val and "reorder_level" in val


# ── JSON format: output is valid parseable JSON string ───────────────

def test_json_format_is_valid_json():
    items = {"x": {"quantity": 99, "reorder_level": 1}}
    result = format_table(items, fmt="json")
    # must not raise
    json.loads(result)


# ── default fmt is "text" ────────────────────────────────────────────

def test_default_fmt_is_text():
    items = {"w": {"quantity": 3, "reorder_level": 5}}
    result = format_table(items)  # no fmt arg
    assert "LOW" in result  # text table contains LOW flag


# ── unknown fmt raises ValueError ────────────────────────────────────

def test_unknown_fmt_raises():
    items = {"w": {"quantity": 3, "reorder_level": 5}}
    try:
        format_table(items, fmt="csv")
        raise AssertionError("expected ValueError for unknown fmt")
    except ValueError:
        pass

